// ===== v6 ACUMULADO CONTINUO (12/08/2026) =====
// Sem week_label: analisa o ACUMULADO nao-analisado por vendedor (conversations.analyzed_at IS NULL),
// monta o markdown aqui mesmo (weekly_batches aposentada), grava ai_analyses com periodo coberto
// (week_label=null nas novas) e marca analyzed_at nas conversas cobertas.
// force+seller_email sem pendencia = re-analisa as conversas da ULTIMA analise dele (PATCH, revisao+1).
// Mantidos: prompt/feedback da gestao, H5 deterministico (janela = periodo do acumulado),
// paralelo em 3 (teto ~300s da instancia), comparativo (sobre os markdowns da rodada).
// >>> PROIBICAO DURA: nada de seller_results em prompt. <<<
const SU='https://mwlxudtdvflygvewuwal.supabase.co';
const SK='eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im13bHh1ZHRkdmZseWd2ZXd1d2FsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODQ4MTI5NDgsImV4cCI6MjEwMDM4ODk0OH0.Hwix2vzrTiAfQwa993TVQTTE8ndCnlXKSew3qh4D57Q';
const H={apikey:SK,Authorization:'Bearer '+SK,'Content-Type':'application/json'};
const HU=Object.assign({},H,{Prefer:'return=representation'});
const HM=Object.assign({},H,{Prefer:'resolution=merge-duplicates,return=minimal'});
const OA=['sk-proj-ItuI3TXbU5xBDw9HBjUkqDmJRLq0QgRL','wqFN55nLNS7km94sl8uvKncbLGKfhqvooG1aCfF1kwT3BlbkFJGtO39DuAid','5RnMuvIQFPzMSY4kXEHU5NxeAub647sTNFZZ_8EJHsnTQjPc2mYTp0Br9hIc_bkA'].join('');  // partida p/ passar no secret-scanning do repo
const MODELO='gpt-5.6-terra';
const get=async p=>{const r=await this.helpers.httpRequest({method:'GET',url:SU+'/rest/v1/'+p,headers:H,json:true});return Array.isArray(r)?r:[];};

const inp=$input.first().json||{};
let body=inp.body;if(typeof body==='string'){try{body=JSON.parse(body);}catch(e){body={};}}
if(!body||typeof body!=='object')body={};
const soVend=String(body.seller_email||'').trim();
const force=body.force===true||String(body.force||'').toLowerCase()==='true';

let lock=null;
try{lock=await this.helpers.httpRequest({method:'POST',url:SU+'/rest/v1/rpc/try_lock',headers:H,body:{p_job:'analisar-acumulado',p_ttl_minutes:20},json:true});}catch(e){}
if(lock!==true)return[{json:{ok:false,erro:'ja existe uma analise rodando'}}];
const solta=async()=>{try{await this.helpers.httpRequest({method:'POST',url:SU+'/rest/v1/rpc/release_lock',headers:H,body:{p_job:'analisar-acumulado'},json:true});}catch(e){}};

const cnt=x=>{if(!x||typeof x!=='object')return{presente_em:0,total:0,conversas_ausentes:[]};
  return{presente_em:Number(x.presente_em)||0,total:Number(x.total)||0,conversas_ausentes:Array.isArray(x.conversas_ausentes)?x.conversas_ausentes:[]};};
const maj=o=>{const c=cnt(o);return c.total>0&&(c.presente_em/c.total)>=0.5;};
const remap=obj=>{const out={};for(const k of Object.keys(obj||{}))out[k]=cnt(obj[k]);return out;};
const STAGES_AVANCO=['Avaliação Agendada','Presença confirmada','Aguardando compra','Em negociação','Fechado'];
const CRIT5=['compromisso_condicional','concessao_com_contrapartida','objecao_isolada','friccao_removida','reengajou_com_prazo'];
const NSUP=t=>String(t||'').indexOf('[formato-nao-suportado')===0;
const ts=m=>m.created_at?new Date(m.created_at).getTime():null;
const temLead=c=>(c.raw_messages||[]).some(m=>m.type!=='USER'&&m.content_type&&m.content_type!=='EVENT'&&m.content_type!=='REACTION');
const wlDe=d=>{const x=new Date(d+'T12:00:00Z');const dow=x.getUTCDay();const mon=new Date(x);mon.setUTCDate(x.getUTCDate()+(dow===0?-6:1-dow));
  const j=new Date(Date.UTC(mon.getUTCFullYear(),0,1));const n=String(Math.ceil(((mon-j)/86400000+j.getUTCDay()+1)/7)).padStart(2,'0');
  return mon.getUTCFullYear()+'-W'+n;};

function calcMetricas(c,etapa){
  const msgs=(c.raw_messages||[]).filter(m=>m.content_type&&m.content_type!=='EVENT'&&m.content_type!=='REACTION'&&ts(m)).sort((a,b)=>ts(a)-ts(b));
  if(!msgs.length)return null;
  const vend=msgs.filter(m=>m.type==='USER');const lead=msgs.filter(m=>m.type!=='USER');
  const audios=msgs.filter(m=>m.content_type==='AUDIO'&&!NSUP(m.transcricao));
  const textos=msgs.filter(m=>m.content_type==='TEXT');
  const durs=audios.map(m=>Number(m.seconds)||0).filter(x=>x>0);
  let first=null;
  if(lead[0]){const r=vend.find(m=>ts(m)>ts(lead[0]));if(r)first=Math.round((ts(r)-ts(lead[0]))/1000);}
  const gaps=[];
  for(let i=1;i<msgs.length;i++){if(msgs[i].type==='USER'&&msgs[i-1].type!=='USER'){const g=(ts(msgs[i])-ts(msgs[i-1]))/1000;if(g>=0&&g<259200)gaps.push(g);}}
  let fups=0;
  for(let i=1;i<msgs.length;i++){if(msgs[i].type==='USER'&&msgs[i-1].type==='USER'&&(ts(msgs[i])-ts(msgs[i-1]))/3600000>=4)fups++;}
  const tot=audios.length+textos.length;
  return{conversation_id:c.id,deal_id:c.deal_id,seller_email:c.seller_email,seller_name:c.seller_name,etapa:etapa,week_label:wlDe(c.conversation_date),
    first_response_seconds:first,
    avg_response_seconds:gaps.length?Math.round(gaps.reduce((a,b)=>a+b,0)/gaps.length):null,
    messages_total:msgs.length,
    conversation_duration_seconds:Math.round((ts(msgs[msgs.length-1])-ts(msgs[0]))/1000),
    audio_count:audios.length,text_count:textos.length,
    audio_percentage:tot?Math.round(1000*audios.length/tot)/10:0,
    avg_audio_seconds:durs.length?Math.round(durs.reduce((a,b)=>a+b,0)/durs.length):null,
    primeira_msg_audio:vend[0]?(vend[0].content_type==='AUDIO'&&!NSUP(vend[0].transcricao)):false,
    ratio_vendedor_lead:lead.length?Math.round(100*vend.length/lead.length)/100:null,
    followups_realizados:fups,is_outlier_slow:first!=null&&first>3600,calculado_em:new Date().toISOString()};
}

function montaMd(nome,convs,ini,fim){
  convs.sort((a,b)=>{if(a.etapa!==b.etapa)return a.etapa==='avaliacao'?-1:1;
    return String(a.conv.conversation_date||'').localeCompare(String(b.conv.conversation_date||''));});
  const nA=convs.filter(x=>x.etapa==='avaliacao').length,nC=convs.length-nA;
  let md='# Vendedor: '+nome+' | Período analisado: '+ini+' a '+fim+'\n';
  md+='Total de conversas: '+convs.length+' ('+nA+' Aval + '+nC+' Closer)\n\n---\n\n';
  for(let i=0;i<convs.length;i++){
    const c=convs[i].conv,rot=convs[i].etapa==='closer'?'Closer':'Aval';
    const msgs=c.raw_messages||[];
    const aud=msgs.filter(m=>m.content_type==='AUDIO'&&!NSUP(m.transcricao));
    const audOk=aud.filter(m=>m.transcricao&&String(m.transcricao).indexOf('[')!==0);
    md+='## Conversa '+(i+1)+' ['+rot+'] | '+(c.stage_atual||'?')+' | Data: '+c.conversation_date+'\n';
    md+='Msgs: '+msgs.length+' | Audios: '+audOk.length+'/'+aud.length+'\n\n';
    for(const m of msgs){
      if(!m.content_type||m.content_type==='EVENT'||m.content_type==='REACTION')continue;
      if(m.content_type==='AUDIO'&&NSUP(m.transcricao))continue;
      const a=m.type==='USER'?'[V]':'[L]';const h=m.created_at?String(m.created_at).slice(11,16):'';
      if(m.content_type==='AUDIO'&&m.transcricao&&String(m.transcricao).indexOf('[')!==0)md+=a+' '+h+': '+String(m.transcricao).trim()+'\n';
      else if(m.content_type==='TEXT'&&m.content)md+=a+' '+h+': '+String(m.content).slice(0,400)+'\n';
      else if(m.content_type==='IMAGE')md+=a+' '+h+': [img]\n';
      else if(m.content_type==='TEMPLATE')md+=a+' '+h+': [template]\n';
    }
    md+='\n---\n\n';
  }
  return md;
}

try{
  const pr=await get('analysis_prompts?select=*&ativo=eq.true&limit=1');
  if(!pr.length){await solta();return[{json:{ok:false,erro:'nenhum prompt ativo'}}];}
  const pi=pr[0].prompt_individual||'';const pc=pr[0].prompt_comparativo||'';
  if(!pi){await solta();return[{json:{ok:false,erro:'prompt individual vazio'}}];}

  let pesos={p:0.40,t:0.30,o:0.30};
  try{const w=await get('score_weights?select=*&order=vigente_desde.desc&limit=1');
    if(w.length)pesos={p:Number(w[0].peso_processo),t:Number(w[0].peso_tecnica),o:Number(w[0].peso_objetivo)};}catch(e){}

  let fbAll=[];
  try{fbAll=await get('analysis_feedback?select=id,escopo,tipo,seller_email,week_label,target_tipo,target_ref,conversa_n,texto,regra&ativo=eq.true&order=criado_em.asc&limit=300');}catch(e){}
  const T_REG=4500,T_CRI=3500,T_COR=2500,MAX_COR=6;
  const corta=(s,n)=>s.length<=n?s:s.slice(0,n)+'\n[...lista truncada por tamanho...]';
  const linha=f=>{const c=String(f.regra||f.texto||'').trim();if(!c)return '';
    const onde=[];if(f.target_ref)onde.push('ref '+f.target_ref);if(f.conversa_n)onde.push('conversa '+f.conversa_n);
    return '- '+c+(onde.length?'  ['+onde.join(' · ')+']':'');};
  const regras=fbAll.filter(f=>f.tipo==='regra_operacional');
  const criterios=fbAll.filter(f=>f.tipo==='criterio');
  function blocoFb(email){
    const ids=[];let s='';
    if(regras.length){const l=regras.map(f=>{ids.push(f.id);return linha(f);}).filter(Boolean).join('\n');
      s+='\n\n## REGRAS OPERACIONAIS CONFIRMADAS PELA GESTAO\nDescrevem o que o processo comercial da Aspekto PERMITE ou PROIBE, e o que e discurso autorizado da casa.\nTEM PRECEDENCIA SOBRE A SUA AVALIACAO: se uma regra diz que algo nao e possivel no processo, voce NAO pode\ncobrar isso do vendedor como falha nem recomendar o contrario. Se diz que uma fala e autorizada, nao a trate\ncomo erro. Quando uma regra contradiz o que voce apontaria, siga a regra e nao registre o ponto.\n'+corta(l,T_REG)+'\n';}
    if(criterios.length){const l=criterios.map(f=>{ids.push(f.id);return linha(f);}).filter(Boolean).join('\n');
      s+='\n\n## CRITERIOS DE AVALIACAO (a regua)\nO gestor definiu que estes pontos devem ser olhados e pesados na nota. Sao regua, nao fato do processo:\nuse para orientar o que observar e o que penalizar. Onde um criterio conflitar com uma regra operacional,\na regra vence.\n'+corta(l,T_CRI)+'\n';}
    const cor=fbAll.filter(f=>(f.tipo==='contesta'||f.tipo==='complementa')&&(!f.seller_email||f.seller_email===email)).slice(-MAX_COR);
    if(cor.length){const l=cor.map(f=>{ids.push(f.id);return linha(f);}).filter(Boolean).join('\n');
      s+='\n\n## CORRECOES DA GESTAO EM ANALISES ANTERIORES DESTE VENDEDOR\nO gestor contestou ou complementou os pontos abaixo. Nao repita o mesmo erro de leitura:\n'+corta(l,T_COR)+'\n';}
    return {texto:s,ids:ids};
  }

  // ===== PENDENCIAS (fila_v5) =====
  let fila=await get('fila_v5?select=*'+(soVend?'&seller_email=eq.'+encodeURIComponent(soVend):''));
  let modo='pendencias';
  let ultimaRe=null;
  if(!fila.length&&force&&soVend){
    const ult=await get('ai_analyses?select=*&seller_email=eq.'+encodeURIComponent(soVend)+'&order=created_at.desc&limit=1');
    if(ult.length&&Array.isArray(ult[0].conversation_ids)&&ult[0].conversation_ids.length){
      modo='reanalise';ultimaRe=ult[0];
      fila=[{seller_email:ult[0].seller_email,seller_name:ult[0].seller_name,conversas:ult[0].conversation_ids.length}];
    }
  }
  if(!fila.length){await solta();return[{json:{ok:true,analisados:0,msg:'nada pendente'}}];}

  const chamar=async(sys,txt)=>{
    const r=await this.helpers.httpRequest({method:'POST',url:'https://api.openai.com/v1/chat/completions',
      headers:{Authorization:'Bearer '+OA,'Content-Type':'application/json'},
      body:{model:MODELO,messages:[{role:'system',content:sys},{role:'user',content:txt}],
        max_completion_tokens:16000,reasoning_effort:'medium',response_format:{type:'json_object'}},json:true,timeout:180000});
    const c=(((r.choices||[])[0]||{}).message||{}).content||'';
    if(!c)throw new Error('resposta vazia do modelo');
    return JSON.parse(c.replace(/```json|```/g,'').trim());};
  const SYS_I='Voce analisa performance de vendedores e mede evolucao. Analise PADRAO, nunca leads individuais, nunca cite nome de paciente. Conte conversa por conversa nos obrigatorios e sinais. Regras operacionais confirmadas pela gestao tem precedencia sobre a sua avaliacao. Responda APENAS com JSON valido.';
  const SYS_C='Voce faz analise comparativa de vendas. Analise PADRAO, nunca cite nome de paciente. Responda APENAS com JSON valido.';

  const res=[];let falhas=0;const mdsRodada=[];
  const processa=async(f)=>{
    try{
      let cs;
      if(modo==='reanalise'){
        cs=await get('conversations?select=id,deal_id,contact_id,seller_email,seller_name,origin_id,origin_name,stage_atual,deal_status,conversation_date,raw_messages&id=in.('+ultimaRe.conversation_ids.map(x=>'"'+x+'"').join(',')+')&limit=500');
      }else{
        cs=await get('conversations?select=id,deal_id,contact_id,seller_email,seller_name,origin_id,origin_name,stage_atual,deal_status,conversation_date,raw_messages&seller_email=eq.'+encodeURIComponent(f.seller_email)+'&analyzed_at=is.null&or=(origin_name.ilike.*closer*,origin_name.ilike.*avalia*)&limit=500');
      }
      cs=cs.filter(temLead);
      if(!cs.length){res.push({vendedor:(f.seller_name||'').trim(),msg:'sem conversas com lead'});return;}
      const nome=(cs[0].seller_name||f.seller_name||'').trim();
      const datas=cs.map(c=>String(c.conversation_date)).sort();
      const ini=datas[0],fim=datas[datas.length-1];
      const convs=cs.map(c=>({conv:c,etapa:(c.origin_name||'').toLowerCase().indexOf('closer')>=0?'closer':'avaliacao'}));
      const md=montaMd(nome,convs,ini,fim);
      const metricas=convs.map(x=>calcMetricas(x.conv,x.etapa)).filter(Boolean);

      const pv=await get('ai_analyses?select=*&seller_email=eq.'+encodeURIComponent(f.seller_email)+'&order=created_at.desc&limit=1');
      const prev=(modo==='reanalise')?null:pv[0];
      let ctx='';
      if(prev){ctx='\n\n## CONTEXTO - ANALISE ANTERIOR ('+(prev.periodo_inicio?prev.periodo_inicio+' a '+prev.periodo_fim:prev.week_label)+')\nScore anterior: '+prev.score_geral
        +'\nPontos apontados: '+JSON.stringify(prev.pontos_de_melhoria||[])
        +'\nMetas definidas: '+JSON.stringify(prev.metas_proximas||[])
        +'\n\nAvalie se houve evolucao nesses pontos. Inclua evolucao e metas_cumpridas no JSON.\n';}

      const fb=blocoFb(f.seller_email);
      const a=await chamar(SYS_I,pi+fb.texto+ctx+'\n\n---\n\n'+md);

      const obrig=remap(a.obrigatorios||{});
      const sinais=remap(a.etapas_cumpridas||{});
      const preco_bool=maj(obrig.conversou_sobre_valores);
      const obj_cont=typeof a.objecoes_contornadas==='boolean'?a.objecoes_contornadas:maj(sinais.dor_resolvida);

      if(metricas.length){
        try{await this.helpers.httpRequest({method:'POST',url:SU+'/rest/v1/objective_metrics?on_conflict=conversation_id',headers:HM,body:metricas,json:true});}catch(e){}
      }
      let sObj=null;
      try{const so=await get('score_objetivo_calc?select=conversation_id,score_objetivo&conversation_id=in.('+cs.map(x=>'"'+x.id+'"').join(',')+')&limit=500');
        if(so.length)sObj=Number((so.reduce((s,x)=>s+Number(x.score_objetivo||0),0)/so.length).toFixed(2));}catch(e){}
      const sPro=a.score_processo!=null?Number(a.score_processo):null;
      const sTec=a.score_tecnica!=null?Number(a.score_tecnica):null;

      // H5 deterministico — janela = periodo do acumulado
      let tecCalc=null;
      try{
        const ids=cs.map(x=>x.id);
        const at=await get('conversa_atividade?select=id,ultima_msg_lead&id=in.('+ids.map(x=>'"'+x+'"').join(',')+')&limit=500');
        const fimX=new Date(fim+'T00:00:00Z');fimX.setUTCDate(fimX.getUTCDate()+1);
        const fimS=fimX.toISOString().slice(0,10);
        const falou=new Set(at.filter(x=>x.ultima_msg_lead&&String(x.ultima_msg_lead).slice(0,10)>=ini&&String(x.ultima_msg_lead).slice(0,10)<fimS).map(x=>x.id));
        let reais=0,reaisStage=0,avanc=0;
        for(const c of cs){if(!falou.has(c.id))continue;reais++;
          if(c.stage_atual!=null){reaisStage++;if(c.deal_status==='WON'||STAGES_AVANCO.indexOf(c.stage_atual)>=0)avanc++;}}
        let sp=0,st2=0,neg=0;
        for(const k of CRIT5){const c=cnt(sinais[k]);sp+=c.presente_em;st2+=c.total;
          if(k==='compromisso_condicional'||k==='concessao_com_contrapartida')neg=Math.max(neg,c.total);}
        const cTaxa=st2>0?10*sp/st2:null;
        const cAvanco=reaisStage>0?10*avanc/reaisStage:null;
        const cDens=reais>0?10*Math.min(1,neg/(0.5*reais)):null;
        const partes=[[cTaxa,0.45],[cAvanco,0.35],[cDens,0.20]].filter(x=>x[0]!=null);
        if(partes.length){
          const spz=partes.reduce((s,x)=>s+x[1],0);
          const bruta=partes.reduce((s,x)=>s+x[0]*x[1],0)/spz;
          const conf=Math.min(1,reais/8);
          const fin=Number((5+(bruta-5)*conf).toFixed(2));
          tecCalc={origem:'calc',formula:'0.45*taxa_pool+0.35*avanco_mec+0.20*densidade; amostra<8 encolhe p/ 5',
            taxa_pool:sp+'/'+st2,avanco_mec:avanc+'/'+reaisStage,negociacoes:neg,conversas_reais:reais,
            c_taxa:cTaxa!=null?Number(cTaxa.toFixed(2)):null,c_avanco:cAvanco!=null?Number(cAvanco.toFixed(2)):null,
            c_dens:cDens!=null?Number(cDens.toFixed(2)):null,bruta:Number(bruta.toFixed(2)),confianca:Number(conf.toFixed(2)),
            tecnica_ia:sTec,tecnica_final:fin,stages_avanco:STAGES_AVANCO};}
      }catch(e){tecCalc={origem:'falha',erro:String((e&&e.message)||e).slice(0,150),tecnica_ia:sTec};}
      const sTecFinal=(tecCalc&&tecCalc.origem==='calc')?tecCalc.tecnica_final:sTec;

      const pp=[[sPro,pesos.p],[sTecFinal,pesos.t],[sObj,pesos.o]].filter(x=>x[0]!=null);
      const sp2=pp.reduce((s,x)=>s+x[1],0);
      const geral=pp.length&&sp2>0?Number((pp.reduce((s,x)=>s+x[0]*x[1],0)/sp2).toFixed(2)):(a.score_geral!=null?Number(a.score_geral):null);
      const delta=(prev&&prev.score_geral!=null&&geral!=null)?Number((geral-prev.score_geral).toFixed(2)):null;
      let urg=a.urgencia_score!=null?Number(a.urgencia_score):null;
      if(urg!=null)urg=Math.max(0,Math.min(10,isNaN(urg)?0:urg));
      const sug=a.sugestoes_metodo&&typeof a.sugestoes_metodo==='object'?a.sugestoes_metodo:{processo_de_vendas:[],criterios_de_avaliacao:[]};

      const reg={week_label:null,seller_email:f.seller_email,seller_name:nome,
        etapa:'combinado',total_conversas:cs.length,deal_ids:cs.map(x=>x.deal_id).filter(Boolean),
        conversation_ids:cs.map(x=>x.id),periodo_inicio:ini,periodo_fim:fim,markdown_content:md,
        score_geral:geral,score_processo:sPro,score_tecnica:sTecFinal,score_objetivo:sObj,urgencia_score:urg,
        preco_mencionado:preco_bool,objecoes_contornadas:obj_cont,
        obrigatorios:obrig,etapas_cumpridas:sinais,tecnica_calc:tecCalc,
        tecnicas_utilizadas:a.tecnicas_utilizadas||[],
        tecnicas_bem_aplicadas:a.tecnicas_bem_aplicadas||[],objecoes_identificadas:a.objecoes_identificadas||[],
        pontos_de_melhoria:a.pontos_de_melhoria||[],resumo_conversa:a.resumo||a.resumo_conversa||'',
        pontos_categorizados:a.pontos_categorizados||[],erros_graves:a.erros_graves||[],
        referencia_qualidade:a.referencia_qualidade||null,referencia_melhoria:a.referencia_melhoria||null,
        evolucao:a.evolucao||null,metas_cumpridas:a.metas_cumpridas||[],
        metas_proximas:a.metas_proximas||a.pontos_de_melhoria||[],sugestoes_metodo:sug,
        feedback_aplicado:fb.ids.length?{ids:fb.ids,total:fb.ids.length,aplicado_em:new Date().toISOString()}:null,
        previous_analysis_id:prev?prev.id:null,previous_week_label:prev?(prev.week_label||String(prev.created_at||'').slice(0,10)):null,score_delta:delta,
        prompt_version:pr[0].nome,modelo:MODELO,created_at:new Date().toISOString()};

      let aid=null;
      if(modo==='reanalise'){
        reg.revisao=(Number(ultimaRe.revisao)||1)+1;
        reg.created_at=undefined;
        const up=await this.helpers.httpRequest({method:'PATCH',url:SU+'/rest/v1/ai_analyses?id=eq.'+ultimaRe.id,headers:HU,body:reg,json:true});
        aid=ultimaRe.id;
      }else{
        reg.revisao=1;
        const sv=await this.helpers.httpRequest({method:'POST',url:SU+'/rest/v1/ai_analyses',headers:HU,body:reg,json:true});
        aid=Array.isArray(sv)?(sv[0]||{}).id:null;
        // marca cobertura — SO depois da analise gravada
        await this.helpers.httpRequest({method:'PATCH',url:SU+'/rest/v1/conversations?id=in.('+cs.map(x=>'"'+x.id+'"').join(',')+')',
          headers:HM,body:{analyzed_at:new Date().toISOString()},json:true});
        const ad=cs.map(c=>({contact_id:c.contact_id,origin_id:c.origin_id,deal_id:c.deal_id,analysis_id:aid,
          seller_email:f.seller_email,seller_name:nome,etapa:'combinado',week_label:wlDe(fim),analyzed_at:new Date().toISOString()}));
        try{await this.helpers.httpRequest({method:'POST',url:SU+'/rest/v1/analyzed_deals?on_conflict=contact_id,origin_id',headers:HM,body:ad,json:true});}catch(e){}
      }
      mdsRodada.push(md);
      res.push({vendedor:nome,score:geral,tecnica:sTecFinal,conversas:cs.length,periodo:ini+' a '+fim,modo:modo,feedback_usado:fb.ids.length});
    }catch(e){falhas++;res.push({vendedor:(f.seller_name||'').trim(),erro:String((e&&e.message)||e).slice(0,200)});}
  };
  for(let i=0;i<fila.length;i+=3){await Promise.all(fila.slice(i,i+3).map(processa));}

  // Comparativo da rodada (>=2 vendedores) — mesma independencia de sempre
  if(pc&&mdsRodada.length>=2){
    try{
      const md=mdsRodada.join('\n\n===PROXIMO VENDEDOR===\n\n');
      const ac=await chamar(SYS_C,pc+'\n\n---\n\n'+md);
      const rl='R-'+new Date().toISOString().slice(0,16).replace('T','-');
      await this.helpers.httpRequest({method:'POST',url:SU+'/rest/v1/weekly_comparative_analyses?on_conflict=week_label',
        headers:HM,body:{week_label:rl,etapa:'combinado',prompt_nome:pr[0].nome,resultado:ac,created_at:new Date().toISOString()},json:true});
      res.push({comparativo:'rodada',vendedores:mdsRodada.length});
    }catch(e){falhas++;res.push({comparativo:'rodada',erro:String((e&&e.message)||e).slice(0,200)});}
  }
  await solta();
  return[{json:{ok:falhas===0,modo:'acumulado',analisados:res.filter(r=>r.score!=null).length,falhas:falhas,resultados:res}}];
}catch(e){await solta();return[{json:{ok:false,erro:String((e&&e.message)||e).slice(0,300)}}];}
